  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  DATE_INVALID: 'Issue date must be a real date in YYYY-MM-DD format.',
  NO_LINES: 'Invoice must have at least one line item.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  LINE_NOT_FOUND: 'That SKU is not on this invoice.',
  NOT_DRAFT: 'Can only modify invoices with status draft.',
  COUNTER_OVERFLOW: 'Too many invoices issued in this year.',
  DISCOUNT_INVALID: 'Discount must be a number from 0 to 100.',
  NOT_ISSUED: 'Can only record payments on issued or partially paid invoices.',
  OVERPAYMENT: 'Payment exceeds the amount owed.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

